# ==========================================================
# 1. USER CONFIGURATION (UPDATE THESE LINES)
# ==========================================================
# Hostinger SFTP/SSH Credentials
$SSHUser = "u835731528"
$SSHHost = "217.21.87.184"
$SSHPort = "65002"

# The local root of your project (where files are staged for deployment)
$LocalProjectRoot = "D:\praveen\dsjv_home"

# The path to your file list
$FilelistPath = "D:\praveen\dsjv_home\backup_file_list.txt"

# >>>>> NEW LINE: Path to your Private Key File (.ppk generated by PuTTYgen) <<<<<
$PrivateKeyPath = "D:\praveen\dsjv_home\keys\hostinger_key.ppk" 

# The root directory on Hostinger (usually public_html or the domain folder)
$RemoteRoot = "/home/u835731528/public_html/dsjv_home/" # IMPORTANT: END with a slash /

# Path to pscp.exe (Update if not in your PATH)
$PscpPath = "pscp.exe"

# ==========================================================
# 2. DEPLOYMENT LOGIC (DO NOT MODIFY)
# ==========================================================

# NOTE: Since we are using the private key, you will be prompted for the KEY PASSPHRASE.
#       This is more secure and reliable than password authentication.

# Read the file list
$FilesToDeploy = Get-Content $FilelistPath

Write-Host "Starting deployment to $SSHUser@$SSHHost via port $SSHPort using key..."
Write-Host "--------------------------------------------------------"

# Loop through each file path and use Pscp to transfer it
foreach ($RelativePath in $FilesToDeploy) {
    
    # 1. Define Local Source Path
    $LocalSourceFile = Join-Path $LocalProjectRoot $RelativePath
    
    # 2. Define Remote Destination Path
    $RemoteDestination = "$($SSHUser)@$($SSHHost):$($RemoteRoot)$($RelativePath)"

    if (Test-Path $LocalSourceFile) {
        
        Write-Host "Deploying: $($RelativePath)"
        
        # Pscp command structure: pscp -P port -i key_file local_file remote_user@remote_host:remote_path
        # The -i $PrivateKeyPath flag tells Pscp to use the key for authentication.
        
        # --- EXECUTE THE TRANSFER ---
        & $PscpPath -P $SSHPort -i $PrivateKeyPath $LocalSourceFile $RemoteDestination 
        
        # Check Pscp exit code (0 usually means success)
        if ($LASTEXITCODE -ne 0) {
            Write-Warning "Pscp failed for file: $($RelativePath). Error code: $($LASTEXITCODE)"
        }
    } else {
        Write-Warning "Skipping: $($RelativePath) not found locally at $($LocalSourceFile)."
    }
}

Write-Host "--------------------------------------------------------"
Write-Host "Deployment attempt complete. Remember to check the remote folders."